def mrconvert_outputs(params: Mrconvert, execution: Execution) -> MrconvertOutputs:
    """Build the MrconvertOutputs object for this tool."""
    json_export_v: OutputPathType | None = None
    export_grad_mrtrix_v: OutputPathType | None = None
    export_pe_table_v: OutputPathType | None = None
