    output_v: OutputPathType = execution.output_file(params["output"])
    __v0 = params.get("json_export")
    if __v0 is not None:
        json_export_v = execution.output_file((__v0 if __v0 is not None else ""))
    __v1 = params.get("export_grad_mrtrix")
